const items = $input.all();

const pesoPrioridad = {
  Alta: 3,
  Media: 2,
  Baja: 1,
};

items.sort((a, b) => {
  const prioridadA = pesoPrioridad[a.json.Prioridad] || 0;
  const prioridadB = pesoPrioridad[b.json.Prioridad] || 0;

  if (prioridadA !== prioridadB) {
    return prioridadB - prioridadA;
  }

  const filaA = Number(a.json.row_number || 0);
  const filaB = Number(b.json.row_number || 0);

  return filaB - filaA;
});

return items;

