const items = $input.all();

return items.map((item, index) => {

  const origen = $('07 - Preparar Web para Buscar Email')
    .itemMatching(index)
    .json;

  const html = String(
    item.json.data ??
    item.json.body ??
    ''
  );

  const encontrados = html.match(
    /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi
  ) || [];

  const emailsLimpios = [...new Set(
    encontrados
      .map(email => email.toLowerCase().trim())
      .filter(email => {

        const bloqueados = [
          'usuario@dominio.com',
          'email@dominio.com',
          'nombre@dominio.com',
          'test@example.com'
        ];

        if (bloqueados.includes(email)) {
          return false;
        }

        if (
          email.includes('example.com') ||
          email.includes('dominio.com') ||
          email.includes('sentry.io') ||
          email.includes('wixpress.com') ||
          email.includes('wordpress.org')
        ) {
          return false;
        }

        return true;
      })
  )];

  // Priorizar emails comerciales/genéricos útiles
  const prioridad = [
    'info@',
    'contacto@',
    'recepcion@',
    'administracion@',
    'comercial@',
    'hola@'
  ];

  emailsLimpios.sort((a, b) => {

    const posA = prioridad.findIndex(prefijo =>
      a.startsWith(prefijo)
    );

    const posB = prioridad.findIndex(prefijo =>
      b.startsWith(prefijo)
    );

    const pesoA = posA === -1 ? 999 : posA;
    const pesoB = posB === -1 ? 999 : posB;

    return pesoA - pesoB;
  });

  return {
    json: {
      row_number: origen.row_number,
      Empresa: origen.Empresa || '',
      Web: origen.Web || '',
      Email: origen.Email || '',

      'Emails Encontrados': emailsLimpios.join(', '),

      'Email Público Encontrado':
        emailsLimpios[0] || '',

      'Cantidad Emails Encontrados':
        emailsLimpios.length,

      'Estado Búsqueda Email':
        emailsLimpios.length > 0
          ? 'Email encontrado'
          : 'Email no encontrado en página principal'
    },

    pairedItem: {
      item: index
    }
  };
});

