const items = $input.all();

const rutas = [
  '/contacto',
  '/contact',
  '/aviso-legal',
  '/legal'
];

const salida = [];

items.forEach((item, index) => {
  const datos = item.json;
  const web = String(datos.Web || '').trim();

  // Obtener solo https://dominio.com
  const coincidencia = web.match(/^(https?:\/\/[^\/?#]+)/i);

  if (!coincidencia) {
    return;
  }

  const dominio = coincidencia[1].replace(/\/$/, '');

  rutas.forEach(ruta => {
    salida.push({
      json: {
        row_number: datos.row_number,
        Empresa: datos.Empresa || '',
        Web: web,
        'URL Secundaria': `${dominio}${ruta}`
      },
      pairedItem: {
        item: index
      }
    });
  });
});

return salida;

const items = $input.all();

const empresas = {};

function limpiarEmails(html) {
  const encontrados = String(html).match(
    /[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi
  ) || [];

  return [...new Set(
    encontrados
      .map(email => email.toLowerCase().trim())
      .filter(email =>
        !email.includes('example.com') &&
        !email.includes('dominio.com') &&
        !email.includes('sentry.io') &&
        !email.includes('wixpress.com') &&
        !email.includes('wordpress.org')
      )
  )];
}

items.forEach((item, index) => {

  const origen = $('13 - Preparar Páginas Secundarias para Buscar Email')
    .itemMatching(index)
    .json;

  const html = String(
    item.json.data ??
    item.json.body ??
    ''
  );

  const emails = limpiarEmails(html);

  const fila = String(origen.row_number);

  if (!empresas[fila]) {
    empresas[fila] = {
      row_number: origen.row_number,
      Empresa: origen.Empresa || '',
      Web: origen.Web || '',
      emails: []
    };
  }

  empresas[fila].emails.push(...emails);
});

return Object.values(empresas).map(empresa => {

  const emails = [...new Set(empresa.emails)];

  const prioridad = [
    'info@',
    'contacto@',
    'recepcion@',
    'administracion@',
    'comercial@',
    'hola@'
  ];

  emails.sort((a, b) => {
    const aPos = prioridad.findIndex(p => a.startsWith(p));
    const bPos = prioridad.findIndex(p => b.startsWith(p));

    return (aPos === -1 ? 999 : aPos) -
           (bPos === -1 ? 999 : bPos);
  });

  return {
    json: {
      row_number: empresa.row_number,
      Empresa: empresa.Empresa,
      Web: empresa.Web,
      'Emails Encontrados Secundarios': emails.join(', '),
      'Email Público Encontrado': emails[0] || '',
      'Cantidad Emails Encontrados': emails.length,
      'Estado Búsqueda Email':
        emails.length > 0
          ? 'Email encontrado en página secundaria'
          : 'Email no encontrado'
    }
  };
});

