const items = $input.all();

return items.map(item => {

  const textoOriginal = String(item.json.text || '').trim();

  try {
    const textoLimpio = textoOriginal
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();

    const datos = JSON.parse(textoLimpio);

    return {
      json: {
        row_number: datos.row_number || '',
        Empresa: datos.empresa || '',
        Email: datos.email_destinatario || '',
        Asunto: datos.asunto || '',
        'Cuerpo Email': datos.cuerpo_email || '',
        'Estado Email Comercial':
          datos.estado_email || 'Pendiente de aprobación',
        'Estado Parseo Email IA': 'Correcto'
      }
    };

  } catch (error) {

    return {
      json: {
        'Estado Parseo Email IA': 'Error',
        'Texto Original IA': textoOriginal,
        'Error Parseo Email IA': error.message
      }
    };
  }
});

